 if not d.get('successful'): return {'day':day,'error':d.get('error')}
 md=d['data']['markdown']; (out/(day+'.md')).write_text(md)
 urls=re.findall(r'<file src="([^"]+)"',md)
 files=[]
 for i,url in enumerate(urls):
  path=out/(day+('.archive.json' if i==0 else f'.archive{i}.json'))
  if not path.exists():
   try: path.write_bytes(urllib.request.urlopen(html.unescape(url),timeout=60).read())
   except Exception as e: files.append({'error':str(e)}); continue
  raw=path.read_bytes()
