  can(command: string): boolean;
  run(command: string): boolean;
  canUndo(): boolean;
  canRedo(): boolean;
  undo(): boolean;
  redo(): boolean;
  markSaved(): void;
  destroy(): void;
  readonly extensions: ResolvedExtensionRegistry;
}

export interface CreateEditorInput {
  readonly markdown: string;
